93	/// A prompt sent to the harness, and what the harness did with it.
94	struct PromptTask {
95	    /// The prompt as typed, shown until it compiles.
96	    text: SharedString,
97	    compiled: Option<Compiled>,
98	    reply: Reply,
99	    status: TaskStatus,
100	}
