333	/// A row of a task's output table.
334	#[derive(Debug, PartialEq)]
335	enum OutputRow<'a> {
336	    /// Reply text; empty while its first words are on their way.
337	    Text(&'a str),
338	    Tool(&'a ToolCall),
339	    Error(&'a str),
340	    /// The harness is still at work, and nothing is known of what comes next.
341	    Pending,
342	}
343	
344	impl OutputRow<'_> {
345	    /// The kind of the row, as a badge in its own colour, or a skeleton while
346	    /// the kind is not yet known.
347	    fn badge(&self) -> AnyElement {
348	        let (tag, icon, label) = match self {
349	            Self::Text(_) => (Tag::secondary(), IconName::MessageSquare, "Reply"),
350	            Self::Tool(call) => {
351	                let kind = ToolKind::of(&call.name);
352	                (Tag::color(kind.color()), kind.icon(), kind.label())
353	            }
354	            Self::Error(_) => (Tag::danger(), IconName::TriangleAlert, "Error"),
355	            Self::Pending => return Skeleton::new().w(px(84.)).h_6().rounded_md().into_any_element(),
356	        };
357	        tag.text_sm()
358	            .child(
359	                h_flex()
360	                    .gap_1()
361	                    .child(Icon::new(icon).xsmall())
362	                    .child(label),
363	            )
364	            .into_any_element()
365	    }
366	
367	    /// Whether the row is still waiting on part of what it shows: text with no
368	    /// words yet, or a running tool call whose input is not yet known.
369	    fn is_partial(&self) -> bool {
370	        match self {
371	            Self::Text(text) => text.trim().is_empty(),
372	            Self::Tool(call) => call.summary.is_none() && call.state == ToolState::Running,
373	            Self::Error(_) => false,
374	            Self::Pending => true,
375	        }
376	    }
377	}
378	
379	impl Reply {
380	    /// Folds a harness event into the reply. Returns an error to show when the
381	    /// run failed.
382	    pub(crate) fn apply(&mut self, event: HarnessEvent) -> Option<String> {
383	        match event {
384	            // Raw output goes to harness streams, not the task's output.
385	            HarnessEvent::Output(_) => {}
386	            HarnessEvent::TextStarted => self.parts.push(ReplyPart::Text(String::new())),
387	            HarnessEvent::TextDelta(delta) => match self.parts.last_mut() {
388	                Some(ReplyPart::Text(text)) => text.push_str(&delta),
389	                _ => self.parts.push(ReplyPart::Text(delta)),
390	            },
391	            HarnessEvent::ToolStarted { id, name } => self.parts.push(ReplyPart::Tool(ToolCall {
392	                id,
393	                name,
394	                summary: None,
395	                state: ToolState::Running,
396	            })),
397	            HarnessEvent::ToolInput { id, summary } => {
398	                if let Some(call) = self.tool_mut(&id) {
399	                    call.summary = Some(summary);
400	                }
401	            }
402	            HarnessEvent::ToolFinished { id, is_error } => {
403	                if let Some(call) = self.tool_mut(&id) {
404	                    call.state = if is_error {
405	                        ToolState::Failed
406	                    } else {
407	                        ToolState::Done
408	                    };
409	                }
410	            }
411	            HarnessEvent::Finished { is_error, result } => {
412	                self.done = true;
413	                self.settle_tools(if is_error {
414	                    ToolState::Failed
415	                } else {
416	                    ToolState::Done
417	                });
418	                if is_error {
419	                    return Some(if result.is_empty() {
420	                        "The harness reported an error.".into()
421	                    } else {
422	                        result
423	                    });
424	                }
425	                // Nothing streamed (e.g. an older harness): show the result.
426	                if !self.has_text() && !result.is_empty() {
427	                    self.parts.push(ReplyPart::Text(result));
428	                }
429	            }
430	            HarnessEvent::Failed(error) => {
431	                self.done = true;
432	                self.settle_tools(ToolState::Failed);
433	                return Some(error);
434	            }
435	        }
436	        None
437	    }
438	
439	    /// Gives tool calls still running when the run ended the state they ended
440	    /// in, so none is left reading "running".
441	    fn settle_tools(&mut self, state: ToolState) {
442	        for part in &mut self.parts {
443	            if let ReplyPart::Tool(call) = part
444	                && call.state == ToolState::Running
445	            {
446	                call.state = state;
447	            }
448	        }
449	    }
450	
451	    fn tool_mut(&mut self, tool_id: &str) -> Option<&mut ToolCall> {
452	        self.parts.iter_mut().rev().find_map(|part| match part {
453	            ReplyPart::Tool(call) if call.id == tool_id => Some(call),
454	            _ => None,
455	        })
456	    }
457	
458	    /// Whether the run has ended, with a result or without.
459	    pub(crate) fn is_done(&self) -> bool {
460	        self.done
461	    }
462	
463	    /// Adds an error row to the end of the output.
464	    pub(crate) fn push_error(&mut self, error: String) {
465	        self.parts.push(ReplyPart::Error(error));
466	    }
467	
468	    fn has_text(&self) -> bool {
469	        self.parts
470	            .iter()
471	            .any(|part| matches!(part, ReplyPart::Text(text) if !text.trim().is_empty()))
472	    }
473	
474	    /// The rows of the output table, in the order they happened. Text with
475	    /// nothing in it is left out, unless it is the last thing in a reply still
476	    /// streaming. Until the reply is done, it ends in a row that is still
477	    /// filling in, adding a pending row if the last is already complete. Rows
478	    /// only change or are added at the end as the reply streams, so a row
479	    /// keeps its index.
480	    fn rows(&self) -> Vec<OutputRow<'_>> {
481	        let last = self.parts.len().saturating_sub(1);
482	        let mut rows: Vec<_> = self
483	            .parts
484	            .iter()
485	            .enumerate()
486	            .filter_map(|(ix, part)| match part {
487	                ReplyPart::Text(text) if text.trim().is_empty() && (self.done || ix != last) => {
488	                    None
489	                }
490	                ReplyPart::Text(text) => Some(OutputRow::Text(text)),
491	                ReplyPart::Tool(call) => Some(OutputRow::Tool(call)),
492	                ReplyPart::Error(error) => Some(OutputRow::Error(error)),
493	            })
494	            .collect();
495	        if !self.done && !rows.last().is_some_and(OutputRow::is_partial) {
496	            rows.push(OutputRow::Pending);
497	        }
498	        rows
499	    }
500	}
