502	pub struct PromptMode {
503	    /// Every task sent, oldest first; the last heads the view.
504	    tasks: Vec<PromptTask>,
505	    /// The latest task's output, which follows new rows while scrolled to
506	    /// the bottom.
507	    output_scroll: ScrollHandle,
508	    chat_input: Entity<ChatInput>,
509	    /// The harness run in flight, which harness streams show.
510	    run: Option<Entity<HarnessRun>>,
511	    /// The harness is working on the latest task.
512	    working: bool,
513	    /// The project changed while the harness worked; its history loads once
514	    /// the run is over.
515	    history_stale: bool,
516	    _history_load: Task<()>,
517	    /// The header is expanded into the list of every task.
518	    history_expanded: bool,
519	    /// The task opened in the expanded list.
520	    open_task: Option<usize>,
521	    task_list_scroll: ScrollHandle,
522	    /// Prompts waiting for the harness, in the order they were sent.
523	    queue: Vec<QueueItem>,
524	    next_queue_id: usize,
525	    queue_expanded: bool,
526	    /// Send the next queued prompt as soon as the harness is free.
527	    auto_send: bool,
528	    /// A restored queue waits for "Send next" (or auto send being switched
529	    /// on) rather than sending on its own, until it has emptied.
530	    queue_held: bool,
531	    /// The file opened from the project tree, beside the task view.
532	    file: Option<Entity<FileView>>,
533	    file_split: Entity<ResizableState>,
534	    /// The width the task view and any file share, as last laid out.
535	    body_width: Rc<Cell<Pixels>>,
536	    _pending: Task<()>,
537	    _file_subscriptions: Vec<Subscription>,
538	    _subscriptions: Vec<Subscription>,
539	}
