541	impl PromptMode {
542	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
543	        let chat_input = cx.new(|cx| ChatInput::new(window, cx));
544	        let subscriptions = vec![
545	            cx.subscribe_in(
546	                &chat_input,
547	                window,
548	                |this, _, submit: &Submit, window, cx| {
549	                    this.send(submit.text.clone(), submit.mode, window, cx)
550	                },
551	            ),
552	            cx.observe_global::<ProjectDirectory>(|this, cx| {
553	                this.load_queue(cx);
554	                this.load_history(cx);
555	            }),
556	        ];
557	
558	        let mut this = Self {
559	            tasks: Vec::new(),
560	            output_scroll: ScrollHandle::new(),
561	            chat_input,
562	            run: None,
563	            working: false,
564	            history_stale: false,
565	            _history_load: Task::ready(()),
566	            history_expanded: false,
567	            open_task: None,
568	            task_list_scroll: ScrollHandle::new(),
569	            queue: Vec::new(),
570	            next_queue_id: 0,
571	            queue_expanded: false,
572	            auto_send: true,
573	            queue_held: false,
574	            file: None,
575	            file_split: cx.new(|_| ResizableState::default()),
576	            body_width: Rc::default(),
577	            _pending: Task::ready(()),
578	            _file_subscriptions: Vec::new(),
579	            _subscriptions: subscriptions,
580	        };
581	        this.load_queue(cx);
582	        this.load_history(cx);
583	        this
584	    }
