633	    /// Opens a file with the cursor at `position`, first asking whether to
634	    /// discard any unsaved changes to the file it replaces.
635	    fn open_file_at(
636	        &mut self,
637	        path: PathBuf,
638	        position: Option<lsp_types::Position>,
639	        window: &mut Window,
640	        cx: &mut Context<Self>,
641	    ) {
