698	    /// Applies a harness event: raw output to the run, the rest to the task
699	    /// at `ix`.
700	    fn apply_event(&mut self, ix: usize, event: HarnessEvent, cx: &mut Context<Self>) {
701	        if let HarnessEvent::Output(line) = event {
702	            if let Some(run) = &self.run {
703	                run.update(cx, |run, cx| run.push_line(line, cx));
704	            }
705	            return;
706	        }
707	        let Some(task) = self.tasks.get_mut(ix) else {
708	            return;
709	        };
710	        // Follows new output only while already scrolled to the bottom.
711	        let following =
712	            self.output_scroll.offset().y <= -self.output_scroll.max_offset().y + px(1.);
713	        task.apply(event);
714	        if following && ix + 1 == self.tasks.len() {
715	            self.output_scroll.scroll_to_bottom();
716	        }
717	        cx.notify();
718	    }
