755	    /// Replaces the queue with the one saved for the current project. A
756	    /// restored queue waits to be sent.
757	    fn load_queue(&mut self, cx: &mut Context<Self>) {
758	        let saved = ProjectDirectory::get(cx)
759	            .map(|project_dir| prompt_queue::load(&project_dir))
760	            .unwrap_or_default();
761	        self.queue = saved
762	            .into_iter()
763	            .map(|saved| {
764	                self.next_queue_id += 1;
765	                QueueItem {
766	                    id: self.next_queue_id,
767	                    text: saved.text.clone().into(),
768	                    saved: Some(saved),
769	                }
770	            })
771	            .collect();
772	        self.queue_held = !self.queue.is_empty();
773	        cx.notify();
774	    }
