776	    /// Replaces the tasks with those sent before in the current project, read
777	    /// in the background. Tasks are only replaced while the harness is free,
778	    /// so a run's task keeps its index; otherwise the history loads once the
779	    /// run is over, the run's own task among it.
780	    fn load_history(&mut self, cx: &mut Context<Self>) {
781	        if self.working {
782	            self.history_stale = true;
783	            return;
784	        }
785	        self.history_stale = false;
786	        let Some(project_dir) = ProjectDirectory::get(cx) else {
787	            self._history_load = Task::ready(());
788	            return;
789	        };
790	        let load = cx.background_spawn(async move {
791	            prompt_history::load(&project_dir)
792	                .into_iter()
793	                .map(PromptTask::restore)
794	                .collect::<Vec<_>>()
795	        });
796	        self._history_load = cx.spawn(async move |this, cx| {
797	            let tasks = load.await;
798	            this.update(cx, |this, cx| {
799	                if this.working {
800	                    this.history_stale = true;
801	                    return;
802	                }
803	                this.tasks = tasks;
804	                this.open_task = None;
805	                this.output_scroll.set_offset(point(px(0.), px(0.)));
806	                cx.notify();
807	            })
808	            .ok();
809	        });
810	    }
