820	    /// Adds `text` to the end of the queue, then resolves its hidden anchor,
821	    /// with the system prompt of `mode`, and saves it with the project in the
822	    /// background.
823	    fn enqueue(
824	        &mut self,
825	        text: String,
826	        mode: SendMode,
827	        window: &mut Window,
828	        cx: &mut Context<Self>,
829	    ) {
830	        let Some(project_dir) = ProjectDirectory::get(cx) else {
831	            return;
832	        };
833	        self.next_queue_id += 1;
834	        let id = self.next_queue_id;
835	        self.queue.push(QueueItem {
836	            id,
837	            text: text.clone().into(),
838	            saved: None,
839	        });
840	        cx.notify();
841	
842	        let lsp = self.chat_input.read(cx).lsp();
843	        let save = cx.background_spawn({
844	            let project_dir = project_dir.clone();
845	            async move {
846	                let mut anchor = match lsp {
847	                    Some(lsp) => lsp.anchor_for(&text)?,
848	                    None => HiddenAnchor::random(),
849	                };
850	                anchor.system_prompt = Some(hidden_anchor::system_prompt(mode, &project_dir)?);
851	                prompt_queue::add(anchor, text, &project_dir)
852	            }
853	        });
854	        cx.spawn_in(window, async move |this, cx| {
855	            let saved = save.await;
856	            this.update_in(cx, |this, window, cx| {
857	                this.queue_saved(id, saved, &project_dir, window, cx)
858	            })
859	            .ok();
860	        })
861	        .detach();
862	    }
