864	    fn queue_saved(
865	        &mut self,
866	        id: usize,
867	        saved: Result<QueuedPrompt>,
868	        project_dir: &std::path::Path,
869	        window: &mut Window,
870	        cx: &mut Context<Self>,
871	    ) {
872	        let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
873	            // Cancelled while it was saved. A queue left behind by switching
874	            // projects keeps it, for when that project is opened again.
875	            if let Ok(saved) = saved
876	                && ProjectDirectory::get(cx).as_deref() == Some(project_dir)
877	            {
878	                prompt_queue::remove(&saved.file).ok();
879	            }
880	            return;
881	        };
882	        match saved {
883	            Ok(saved) => {
884	                self.queue[ix].saved = Some(saved);
885	                self.auto_send_next(cx);
886	            }
887	            Err(err) => {
888	                self.queue.remove(ix);
889	                window.push_notification(
890	                    Notification::error(format!("{err:#}")).title("Could not queue the prompt"),
891	                    cx,
892	                );
893	            }
894	        }
895	        cx.notify();
896	    }
