898	    /// Sends the first queued prompt, if the harness is free and it is saved.
899	    fn send_next(&mut self, cx: &mut Context<Self>) {
900	        // Without a project it could not be sent, and must stay queued.
901	        if self.working
902	            || ProjectDirectory::get(cx).is_none()
903	            || !self.queue.first().is_some_and(|item| item.saved.is_some())
904	        {
905	            return;
906	        }
907	        let item = self.queue.remove(0);
908	        if self.queue.is_empty() {
909	            self.queue_held = false;
910	        }
911	        let Some(saved) = item.saved else { return };
912	        self.start(item.text.to_string(), Sending::Queued(saved), cx);
913	    }
