922	    /// Removes a prompt that has not been sent from the queue, and its file.
923	    fn cancel(&mut self, id: usize, window: &mut Window, cx: &mut Context<Self>) {
924	        let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
925	            return;
926	        };
927	        let item = self.queue.remove(ix);
928	        if let Some(saved) = &item.saved
929	            && let Err(err) = prompt_queue::remove(&saved.file)
930	        {
931	            // Its file is still there, so it is still queued.
932	            self.queue.insert(ix, item);
933	            window.push_notification(
934	                Notification::error(format!("{err:#}")).title("Could not cancel the prompt"),
935	                cx,
936	            );
937	        }
938	        if self.queue.is_empty() {
939	            self.queue_held = false;
940	        }
941	        cx.notify();
942	    }
