962	    /// Sends `text` to the harness as a new task: a queued prompt with the
963	    /// anchor it was saved with, else with a freshly resolved one.
964	    fn start(&mut self, text: String, sending: Sending, cx: &mut Context<Self>) {
965	        let Some(project_dir) = ProjectDirectory::get(cx) else {
966	            return;
967	        };
968	        let task_ix = self.push_task(text.clone().into(), cx);
969	        self.working = true;
970	        self.chat_input
971	            .update(cx, |input, cx| input.set_busy(true, cx));
972	
973	        let lsp = self.chat_input.read(cx).lsp();
974	        let compile = cx.background_spawn({
975	            let project_dir = project_dir.clone();
976	            async move {
977	                let anchor = match sending {
978	                    // Out of the queue first, so it is never sent twice.
979	                    Sending::Queued(queued) => {
980	                        prompt_queue::remove(&queued.file)?;
981	                        queued.anchor
982	                    }
983	                    // Without `piton lsp` nothing is imported, and any spec
984	                    // name the prompt uses fails to compile with an explicit
985	                    // error.
986	                    Sending::Now(mode) => {
987	                        let mut anchor = match lsp {
988	                            Some(lsp) => lsp.anchor_for(&text)?,
989	                            None => HiddenAnchor::random(),
990	                        };
991	                        anchor.system_prompt =
992	                            Some(hidden_anchor::system_prompt(mode, &project_dir)?);
993	                        anchor
994	                    }
995	                };
996	                let file = hidden_anchor::save(&anchor, &text, &project_dir)?;
997	                let compiled = hidden_anchor::compile(&anchor, &file, &project_dir);
998	                anyhow::Ok((anchor.name().to_string(), file, compiled))
999	            }
1000	        });
1001	
1002	        self._pending = cx.spawn(async move |this, cx| {
1003	            // What came of the prompt, saved beside it in the history once it
1004	            // is over.
1005	            let mut record = RunRecord::default();
1006	            let mut prompt_file = None;
1007	            let compiled = compile.await.and_then(|(anchor, file, compiled)| {
1008	                prompt_file = Some(file);
1009	                Ok((anchor, compiled?))
1010	            });
1011	            match compiled {
1012	                Ok((anchor, compiled)) => {
1013	                    let prompt = compiled.user_prompt;
1014	                    record.user_prompt = Some(prompt.clone());
1015	                    let mut events =
1016	                        harness::send(prompt.clone(), compiled.system_prompt, project_dir);
1017	                    if this
1018	                        .update(cx, |this, cx| {
1019	                            this.show_compiled(task_ix, anchor, prompt, cx);
1020	                            this.run = Some(HarnessRuns::start(cx));
1021	                        })
1022	                        .is_err()
1023	                    {
1024	                        return;
1025	                    }
1026	                    while let Some(event) = events.next().await {
1027	                        record.note(&event);
1028	                        if this
1029	                            .update(cx, |this, cx| this.apply_event(task_ix, event, cx))
1030	                            .is_err()
1031	                        {
1032	                            return;
1033	                        }
1034	                    }
1035	                }
1036	                Err(err) => {
1037	                    let error = format!("{err:#}");
1038	                    record.error = Some(error.clone());
1039	                    this.update(cx, |this, _| {
1040	                        if let Some(task) = this.tasks.get_mut(task_ix) {
1041	                            task.fail(error);
1042	                        }
1043	                    })
1044	                    .ok();
1045	                }
1046	            }
1047	
1048	            // Unsaved (the prompt itself could not be saved) there is nothing
1049	            // to save it beside.
1050	            let saved = match prompt_file {
1051	                Some(file) => {
1052	                    cx.background_spawn(async move { prompt_history::save_record(&file, &record) })
1053	                        .await
1054	                }
1055	                None => Ok(()),
1056	            };
1057	
1058	            this.update(cx, |this, cx| {
1059	                if let Some(task) = this.tasks.get_mut(task_ix) {
1060	                    task.end();
1061	                    if let Err(err) = saved {
1062	                        // Shown without failing the task: the run itself is
1063	                        // unaffected.
1064	                        task.reply.parts.push(ReplyPart::Error(format!(
1065	                            "Could not save this task to the history: {err:#}"
1066	                        )));
1067	                    }
1068	                }
1069	                if let Some(run) = this.run.take() {
1070	                    run.update(cx, |run, cx| run.finish(cx));
1071	                }
1072	                this.working = false;
1073	                if this.history_stale {
1074	                    this.load_history(cx);
1075	                }
1076	                this.chat_input
1077	                    .update(cx, |input, cx| input.set_busy(false, cx));
1078	                // Deferred: starting the next run replaces this task.
1079	                let prompt_mode = cx.entity();
1080	                cx.defer(move |cx| prompt_mode.update(cx, |this, cx| this.auto_send_next(cx)));
1081	                cx.notify();
1082	            })
1083	            .ok();
1084	        });
1085	    }
