1437	/// `text` with the project directory written relative to it: paths inside the
1438	/// directory lose its path, and the directory itself reads `.`. A path that
1439	/// only starts with the same characters, like a sibling directory, is kept.
1440	fn relative_to_project(text: &str, project_dir: Option<&Path>) -> String {
1441	    let Some(dir) = project_dir
1442	        .and_then(Path::to_str)
1443	        .map(|dir| dir.trim_end_matches('/'))
1444	        .filter(|dir| !dir.is_empty())
1445	    else {
1446	        return text.to_string();
1447	    };
1448	    let is_path_char = |c: char| c.is_alphanumeric() || matches!(c, '/' | '.' | '_' | '-' | '~');
1449	    let ends_path = |rest: &str| rest.chars().next().is_none_or(|c| !is_path_char(c));
1450	
1451	    let mut out = String::with_capacity(text.len());
1452	    let mut rest = text;
1453	    while let Some(at) = rest.find(dir) {
1454	        out.push_str(&rest[..at]);
1455	        let after = &rest[at + dir.len()..];
1456	        let starts_path = out.chars().last().is_none_or(|c| !is_path_char(c));
1457	        rest = if starts_path && ends_path(after) {
1458	            out.push('.');
1459	            after
1460	        } else if starts_path && after.starts_with('/') {
1461	            let inside = &after[1..];
1462	            if ends_path(inside) {
1463	                out.push('.');
1464	            }
1465	            inside
1466	        } else {
1467	            out.push_str(dir);
1468	            after
1469	        };
1470	    }
1471	    out.push_str(rest);
1472	    out
1473	}
