1	//! The main window of the application, from which all main functionality is
2	//! reached: a toolbar on top, and below it the project tree in a sidebar on the
3	//! left, then prompt mode with the harness stream split beside it while raw
4	//! output is shown.
5	
6	use gpui_kit::component::button::ButtonVariant;
7	use gpui_kit::component::dialog::DialogButtonProps;
8	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
9	use gpui_kit::component::{ActiveTheme, Root, WindowExt as _};
10	use gpui_kit::*;
11	
12	use crate::app::{APP_TITLE, Quit};
13	use crate::harness_stream::HarnessStream;
14	use crate::palette::{Palette, Picked, SystemCommand, SystemState};
15	use crate::project_tree::{OpenFile, ProjectTree};
16	use crate::prompt_mode::PromptMode;
17	use crate::theme_preference;
18	use crate::toolbar::{self, RawOutputToggled, Toolbar};
19	
20	/// Size the window restores to when it is un-maximized.
21	const RESTORE_SIZE: Size<Pixels> = size(px(1280.), px(800.));
22	
23	/// The narrowest a split can be dragged.
24	const MIN_SPLIT_WIDTH: Pixels = px(240.);
25	
26	/// The sidebar's width until it is dragged, and the narrowest it can be.
27	const SIDEBAR_WIDTH: Pixels = px(260.);
28	const MIN_SIDEBAR_WIDTH: Pixels = px(160.);
29	
30	actions!(suspense, [FocusChat, TogglePalette]);
31	
32	/// Esc anywhere in the window moves focus to the chat input. It is bound
33	/// without a context, so an editor or popup that has something to cancel
34	/// (a completion menu, extra cursors) takes Esc first. Ctrl/Cmd+P opens or
35	/// closes the palette.
36	pub fn bind_keys(cx: &mut App) {
37	    cx.bind_keys([
38	        KeyBinding::new("escape", FocusChat, None),
39	        #[cfg(target_os = "macos")]
40	        KeyBinding::new("cmd-p", TogglePalette, None),
41	        #[cfg(not(target_os = "macos"))]
42	        KeyBinding::new("ctrl-p", TogglePalette, None),
43	    ]);
44	    crate::palette::bind_keys(cx);
45	}
46	
47	pub struct MainWindow {
48	    toolbar: Entity<Toolbar>,
49	    sidebar: Entity<ProjectTree>,
50	    prompt_mode: Entity<PromptMode>,
51	    stream: Option<Entity<HarnessStream>>,
52	    /// The palette last opened, which may since have closed.
53	    palette: Option<Entity<Palette>>,
54	    _palette_subscription: Option<Subscription>,
55	    /// Kept apart from `splits` so the sidebar keeps its width when the
56	    /// stream split opens or closes.
57	    sidebar_split: Entity<ResizableState>,
58	    splits: Entity<ResizableState>,
59	    _subscriptions: Vec<Subscription>,
60	}
61	
62	impl MainWindow {
63	    pub fn open(cx: &mut App) -> Result<WindowHandle<Root>> {
64	        let options = WindowOptions {
65	            window_bounds: Some(WindowBounds::Maximized(Bounds::centered(
66	                None,
67	                RESTORE_SIZE,
68	                cx,
69	            ))),
70	            titlebar: Some(TitlebarOptions {
71	                title: Some(APP_TITLE.into()),
72	                ..Default::default()
73	            }),
74	            ..Default::default()
75	        };
76	
77	        cx.open_window(options, |window, cx| {
78	            // Start in the saved light or dark mode, else the system's; the
79	            // toolbar can switch.
80	            theme_preference::apply(window, cx);
81	            let view = cx.new(|cx| MainWindow::new(window, cx));
82	            cx.new(|cx| Root::new(view, window, cx))
83	        })
84	    }
85	
86	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
87	        let toolbar = cx.new(Toolbar::new);
88	        let sidebar = cx.new(ProjectTree::new);
89	        let subscriptions = vec![
90	            cx.subscribe_in(
91	                &toolbar,
92	                window,
93	                |this, _, event: &RawOutputToggled, window, cx| {
94	                    this.show_stream(event.visible, window, cx)
95	                },
96	            ),
97	            cx.subscribe_in(&sidebar, window, |this, _, OpenFile(path), window, cx| {
98	                this.prompt_mode.update(cx, |prompt_mode, cx| {
99	                    prompt_mode.open_file(path.clone(), window, cx)
100	                })
101	            }),
102	            // Until light or dark mode is chosen, the window keeps following
103	            // the system's appearance as it changes.
104	            cx.observe_window_appearance(window, |_, window, cx| {
105	                theme_preference::apply(window, cx)
106	            }),
107	            // Focus left on nothing, as when a focused file is closed, would
108	            // put Esc out of the window's reach; the chat input takes it.
109	            cx.on_focus_lost(window, |this, window, cx| {
110	                this.prompt_mode
111	                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
112	            }),
113	        ];
114	        // Closing the window ends the application, so it asks first too.
115	        let this = cx.weak_entity();
116	        window.on_window_should_close(cx, move |window, cx| {
117	            this.update(cx, |this, cx| this.confirm_quit(window, cx))
118	                .unwrap_or(true)
119	        });
120	
121	        Self {
122	            toolbar,
123	            sidebar,
124	            prompt_mode: cx.new(|cx| PromptMode::new(window, cx)),
125	            stream: None,
126	            palette: None,
127	            _palette_subscription: None,
128	            sidebar_split: cx.new(|_| ResizableState::default()),
129	            splits: cx.new(|_| ResizableState::default()),
130	            _subscriptions: subscriptions,
131	        }
132	    }
133	
134	    fn show_stream(&mut self, visible: bool, window: &mut Window, cx: &mut Context<Self>) {
135	        self.stream = visible.then(|| cx.new(|cx| HarnessStream::new(window, cx)));
136	        // Fresh split sizes, so none are left over from a closed split.
137	        self.splits = cx.new(|_| ResizableState::default());
138	        cx.notify();
139	    }
140	
141	    /// Quits, once confirmed if a task is running.
142	    fn quit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
143	        if self.confirm_quit(window, cx) {
144	            cx.quit();
145	        }
146	    }
147	
148	    /// Whether the application can end now: nothing is running. While a
149	    /// prompt or a build is, it asks instead, quitting once confirmed.
150	    fn confirm_quit(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
151	        let working = self.prompt_mode.read(cx).is_working();
152	        let building = self.toolbar.read(cx).is_building();
153	        let description = match (working, building) {
154	            (false, false) => return true,
155	            (true, false) => "The harness is still working on a prompt.",
156	            (false, true) => "piton build is still running.",
157	            (true, true) => "The harness is still working on a prompt and piton build is still running.",
158	        };
159	        // An open palette makes way; a confirmation already open stays the
160	        // only one.
161	        if let Some(palette) = &self.palette
162	            && palette.read(cx).is_open(window, cx)
163	        {
164	            window.close_dialog(cx);
165	        }
166	        if !window.has_active_dialog(cx) {
167	            window.open_alert_dialog(cx, move |alert, _, _| {
168	                alert
169	                    .title("Quit while a task is running?")
170	                    .description(description)
171	                    .button_props(
172	                        DialogButtonProps::default()
173	                            .show_cancel(true)
174	                            .ok_text("Quit")
175	                            .ok_variant(ButtonVariant::Danger)
176	                            .cancel_text("Keep Running"),
177	                    )
178	                    .on_ok(|_, _, cx| {
179	                        cx.quit();
180	                        true
181	                    })
182	            });
183	        }
184	        false
185	    }
186	
187	    /// Opens a fresh palette on the Files tab, or closes the one open.
188	    fn toggle_palette(&mut self, window: &mut Window, cx: &mut Context<Self>) {
189	        if let Some(palette) = &self.palette
190	            && palette.read(cx).is_open(window, cx)
191	        {
192	            window.close_dialog(cx);
193	            return;
194	        }
195	        let toolbar = self.toolbar.read(cx);
196	        let system = SystemState {
197	            raw_output_visible: toolbar.raw_output_visible(),
198	            can_build: toolbar.can_build(cx),
199	            dark: cx.theme().is_dark(),
200	        };
201	        let palette = cx.new(|cx| Palette::new(system, window, cx));
202	        self._palette_subscription = Some(cx.subscribe_in(
203	            &palette,
204	            window,
205	            |this, _, picked: &Picked, window, cx| this.run_picked(picked, window, cx),
206	        ));
207	        Palette::open(&palette, window, cx);
208	        self.palette = Some(palette);
209	    }
210	
211	    fn run_picked(&mut self, picked: &Picked, window: &mut Window, cx: &mut Context<Self>) {
212	        match picked {
213	            Picked::File(path) => self.prompt_mode.update(cx, |prompt_mode, cx| {
214	                prompt_mode.open_file(path.clone(), window, cx)
215	            }),
216	            Picked::Mention(mention) => self.prompt_mode.update(cx, |prompt_mode, cx| {
217	                prompt_mode.insert_mention(mention, window, cx)
218	            }),
219	            Picked::System(command) => match command {
220	                SystemCommand::OpenProject => self
221	                    .toolbar
222	                    .update(cx, |toolbar, cx| toolbar.pick_project(window, cx)),
223	                SystemCommand::Build => self
224	                    .toolbar
225	                    .update(cx, |toolbar, cx| toolbar.build(window, cx)),
226	                SystemCommand::ToggleRawOutput => self
227	                    .toolbar
228	                    .update(cx, |toolbar, cx| toolbar.toggle_raw_output(cx)),
229	                SystemCommand::ToggleDarkMode => {
230	                    toolbar::set_dark_mode(!cx.theme().is_dark(), window, cx)
231	                }
232	                SystemCommand::Quit => self.quit(window, cx),
233	            },
234	        }
235	    }
236	}
