238	impl Render for MainWindow {
239	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
240	        div()
241	            .size_full()
242	            .flex()
243	            .flex_col()
244	            .bg(cx.theme().background)
245	            .text_color(cx.theme().foreground)
246	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| {
247	                // The context-less Esc binding outranks the palette's own, so
248	                // the palette's Esc is handled here.
249	                if let Some(palette) = &this.palette
250	                    && palette.read(cx).is_open(window, cx)
251	                {
252	                    palette.update(cx, |palette, cx| palette.cancel(window, cx));
253	                    return;
254	                }
255	                // Likewise any other dialog, such as the quit confirmation.
256	                if window.has_active_dialog(cx) {
257	                    window.close_dialog(cx);
258	                    return;
259	                }
260	                this.prompt_mode
261	                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
262	            }))
263	            .on_action(
264	                cx.listener(|this, _: &TogglePalette, window, cx| this.toggle_palette(window, cx)),
265	            )
266	            .on_action(cx.listener(|this, _: &Quit, window, cx| this.quit(window, cx)))
267	            .child(self.toolbar.clone())
268	            .child(
269	                div().flex_1().min_h_0().child(
270	                    // One `children` call for every panel: the group's
271	                    // `children` replaces panels added before it.
272	                    h_resizable("sidebar-split")
273	                        .with_state(&self.sidebar_split)
274	                        .children([
275	                            resizable_panel()
276	                                .size(SIDEBAR_WIDTH)
277	                                .size_range(MIN_SIDEBAR_WIDTH..Pixels::MAX)
278	                                .child(self.sidebar.clone()),
279	                            resizable_panel()
280	                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
281	                                .child(
282	                                    h_resizable("body").with_state(&self.splits).children(
283	                                        std::iter::once(
284	                                            resizable_panel()
285	                                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
286	                                                .child(self.prompt_mode.clone()),
287	                                        )
288	                                        .chain(
289	                                            self.stream.iter().map(|stream| {
290	                                                let split = div()
291	                                                    .id("stream")
292	                                                    .size_full()
293	                                                    .child(stream.clone());
294	                                                resizable_panel()
295	                                                    .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
296	                                                    // Lets UI tests find the split; inert in normal builds.
297	                                                    .child(gpui_kit::TestSupportExt::test_support(
298	                                                        split,
299	                                                    ))
300	                                            }),
301	                                        ),
302	                                    ),
303	                                ),
304	                        ]),
305	                ),
306	            )
307	            // Inside the window's element tree, so actions such as
308	            // TogglePalette reach it from a focused dialog.
309	            .children(Root::render_dialog_layer(window, cx))
310	            .children(Root::render_notification_layer(window, cx))
311	    }
312	}
