52	/// Appended to the harness's system prompt for a file search in `project_dir`.
53	/// The spec and code locations are read from its `piton.config.pi`; any it
54	/// does not set are left out of the search order.
55	fn search_system_prompt(project_dir: &Path) -> String {
56	    let spec = hidden_anchor::config_value(project_dir, "root").ok();
57	    let code = hidden_anchor::config_value(project_dir, "codeRoot").ok();
58	    let order = [
59	        spec.map(|spec| format!("the spec, in {spec}")),
60	        code.map(|code| format!("the code, in {code}")),
61	        Some(hidden_anchor::APP_DIR.to_string()),
62	        Some(".claude".to_string()),
63	    ]
64	    .into_iter()
65	    .flatten()
66	    .enumerate()
67	    .map(|(index, place)| format!("{}. {place}", index + 1))
68	    .collect::<Vec<_>>()
69	    .join("\n");
70	
71	    format!(
72	        "\
73	You are finding a file in this project for someone who could not find it by \
74	its name. They describe what they are looking for; it may be a partial or \
75	misremembered name, what the file does, or something it contains.
76	
77	Your goal is to identify the one file they mean. Search with tools that only \
78	read, such as Glob, Grep and Read, and never change anything. Stop searching as \
79	soon as you are confident. Only when several files are all genuinely and \
80	equally what was asked for, give each of them; otherwise give the single best \
81	file.
82	
83	Look in these places in this order of priority, preferring a match from an \
84	earlier one over an equally good match from a later one:
85	{order}
86	
87	End with a reply of nothing but JSON, with no prose and no code fence, listing \
88	paths relative to the project directory: {{\"files\": [\"path/to/file\"]}}. If \
89	nothing matches, reply {{\"files\": []}}."
90	    )
91	}
