105	/// The files the harness's final reply names that exist in the project, in
106	/// the order given. The reply's JSON is looked for between its first `{` and
107	/// last `}`, in case it strays from JSON alone.
108	fn found_files(reply: &str, root: &Path) -> Vec<PathBuf> {
109	    let json = match (reply.find('{'), reply.rfind('}')) {
110	        (Some(start), Some(end)) if start < end => &reply[start..=end],
111	        _ => return Vec::new(),
112	    };
113	    let Ok(value) = serde_json::from_str::<serde_json::Value>(json) else {
114	        return Vec::new();
115	    };
116	    let mut files: Vec<PathBuf> = Vec::new();
117	    for path in value
118	        .get("files")
119	        .and_then(serde_json::Value::as_array)
120	        .into_iter()
121	        .flatten()
122	        .filter_map(serde_json::Value::as_str)
123	    {
124	        let path = root.join(path.trim_start_matches("./"));
125	        if path.is_file() && !files.contains(&path) {
126	            files.push(path);
127	        }
128	    }
129	    files
130	}
