285	/// A result as listed: the candidate and the byte offsets of its characters
286	/// the search matched.
287	struct Shown {
288	    candidate: Candidate,
289	    positions: Vec<usize>,
290	}
291	
292	/// The candidates the query matches, best first, up to [`MAX_RESULTS`]. An
293	/// empty query keeps them in their order.
294	fn rank(query: &str, candidates: &[Candidate]) -> Vec<Shown> {
295	    let mut matched: Vec<(i32, &Candidate, Vec<usize>)> = candidates
296	        .iter()
297	        .filter_map(|candidate| {
298	            let found = fuzzy::fuzzy_match(query, candidate.text(), candidate.name_start())?;
299	            Some((found.score, candidate, found.positions))
300	        })
301	        .collect();
302	    if !query.trim().is_empty() {
303	        matched.sort_by(|(a_score, a, _), (b_score, b, _)| {
304	            b_score
305	                .cmp(a_score)
306	                .then_with(|| a.text().len().cmp(&b.text().len()))
307	                .then_with(|| a.text().cmp(b.text()))
308	        });
309	    }
310	    matched
311	        .into_iter()
312	        .take(MAX_RESULTS)
313	        .map(|(_, candidate, positions)| Shown {
314	            candidate: candidate.clone(),
315	            positions,
316	        })
317	        .collect()
318	}
