320	/// Every file under `root`, by its path in the project, leaving out `.git`
321	/// and whatever the project's `.gitignore` files ignore. Blocking.
322	fn list_files(root: &Path) -> Vec<Candidate> {
323	    let mut files: Vec<Candidate> = ignore::WalkBuilder::new(root)
324	        .hidden(false)
325	        .require_git(false)
326	        .filter_entry(|entry| entry.file_name() != ".git")
327	        .build()
328	        .filter_map(Result::ok)
329	        .filter(|entry| entry.file_type().is_some_and(|kind| kind.is_file()))
330	        .take(MAX_FILES)
331	        .filter_map(|entry| {
332	            let relative = entry.path().strip_prefix(root).ok()?;
333	            let label = relative
334	                .components()
335	                .map(|part| part.as_os_str().to_string_lossy())
336	                .collect::<Vec<_>>()
337	                .join("/");
338	            let name_start = label.rfind('/').map_or(0, |ix| ix + 1);
339	            Some(Candidate::File {
340	                path: entry.path().to_path_buf(),
341	                label: label.into(),
342	                name_start,
343	            })
344	        })
345	        .collect();
346	    files.sort_by_cached_key(|file| file.text().to_lowercase());
347	    files
348	}
