513	    /// Hands the search to the harness to find the file it describes. One
514	    /// file found is picked; several are only reported for now. The run's
515	    /// output shows in place of the results meanwhile.
516	    fn search_files(&mut self, window: &mut Window, cx: &mut Context<Self>) {
517	        let Some(root) = self.project.clone().filter(|_| self.can_search_files()) else {
518	            return;
519	        };
520	        if self
521	            .search
522	            .as_ref()
523	            .is_some_and(|search| search.query == self.query && !search.reply.is_done())
524	        {
525	            return;
526	        }
527	        self.stop_search(cx);
528	
529	        let query = self.query.clone();
530	        let prompt = format!("Find the file I'm looking for: {query}");
531	        let mut events =
532	            (self.send_to_harness)(prompt, Some(search_system_prompt(&root)), root.clone());
533	        let run = HarnessRuns::start(cx);
534	        let task = cx.spawn_in(window, async move |this, cx| {
535	            let mut answer = None;
536	            while let Some(event) = events.next().await {
537	                if let HarnessEvent::Finished {
538	                    is_error: false,
539	                    result,
540	                } = &event
541	                {
542	                    answer = Some(result.clone());
543	                }
544	                let applied = this.update(cx, |this, cx| {
545	                    let Some(search) = &mut this.search else {
546	                        return;
547	                    };
548	                    if let HarnessEvent::Output(line) = &event {
549	                        search
550	                            .run
551	                            .update(cx, |run, cx| run.push_line(line.clone(), cx));
552	                    }
553	                    if let Some(error) = search.reply.apply(event) {
554	                        search.reply.push_error(error);
555	                    }
556	                    cx.notify();
557	                });
558	                if applied.is_err() {
559	                    return;
560	                }
561	            }
562	
563	            let answered = answer.is_some();
564	            let files = match answer {
565	                Some(answer) => {
566	                    let root = root.clone();
567	                    cx.background_spawn(async move { found_files(&answer, &root) })
568	                        .await
569	                }
570	                None => Vec::new(),
571	            };
572	            this.update_in(cx, |this, window, cx| {
573	                let Some(search) = &mut this.search else {
574	                    return;
575	                };
576	                search.run.update(cx, |run, cx| run.finish(cx));
577	                if !search.reply.is_done()
578	                    && let Some(error) = search.reply.apply(HarnessEvent::Failed(
579	                        "The harness stopped without a result.".into(),
580	                    ))
581	                {
582	                    search.reply.push_error(error);
583	                }
584	                // A failed run already shows why.
585	                if answered && files.is_empty() {
586	                    search
587	                        .reply
588	                        .push_error("No file matching the search was found.".into());
589	                }
590	                cx.notify();
591	                // Left alone once the palette has closed.
592	                if !this.is_open(window, cx) {
593	                    return;
594	                }
595	                match files.as_slice() {
596	                    [] => {}
597	                    [file] => {
598	                        window.close_dialog(cx);
599	                        cx.emit(Picked::File(file.clone()));
600	                    }
601	                    _ => window.open_alert_dialog(cx, |alert, _, _| {
602	                        alert.title("Multiple results were found")
603	                    }),
604	                }
605	            })
606	            .ok();
607	        });
608	        self.search = Some(FileSearch {
609	            query,
610	            reply: Reply::default(),
611	            run,
612	            _task: task,
613	        });
614	        cx.notify();
615	    }
