617	    /// Drops the harness's search, stopping its run if still going.
618	    fn stop_search(&mut self, cx: &mut Context<Self>) {
619	        if let Some(search) = self.search.take() {
620	            search.run.update(cx, |run, cx| {
621	                if !run.is_done() {
622	                    run.finish(cx)
623	                }
624	            });
625	            cx.notify();
626	        }
627	    }
