630	        if tab == self.tab {
631	            return;
632	        }
633	        self.stop_search(cx);
634	        self.tab = tab;
635	        let query = self.query.clone();
636	        self.command = cx.new(|cx| {
637	            let mut command = CommandState::new(window, cx);
638	            command.set_query(query, window, cx);
