646	    /// Moves `step` tabs along, wrapping around.
647	    fn cycle(&mut self, step: isize, window: &mut Window, cx: &mut Context<Self>) {
648	        let count = PaletteTab::ALL.len() as isize;
649	        let ix = PaletteTab::ALL
650	            .iter()
651	            .position(|tab| *tab == self.tab)
652	            .unwrap_or(0) as isize;
653	        let next = PaletteTab::ALL[(ix + step).rem_euclid(count) as usize];
654	        self.set_tab(next, window, cx);
655	    }
656	
657	    fn pick(&mut self, row: usize, window: &mut Window, cx: &mut Context<Self>) {
658	        let Some(shown) = self.shown.get(row) else {
659	            return;
660	        };
661	        let picked = match &shown.candidate {
662	            Candidate::File { path, .. } => Picked::File(path.clone()),
663	            Candidate::System { enabled: false, .. } => return,
664	            Candidate::System { command, .. } => Picked::System(*command),
665	            Candidate::Mention(invocable) => Picked::Mention(invocable.mention()),
666	        };
667	        window.close_dialog(cx);
668	        cx.emit(picked);
669	    }
670	
671	    fn empty_text(&self) -> &'static str {
672	        let loading = match self.tab {
673	            PaletteTab::Files if self.project.is_none() => return "No project open",
674	            PaletteTab::Files => self.files.is_none(),
675	            PaletteTab::System => false,
676	            _ => self.invocables.is_none(),
677	        };
678	        if loading {
679	            "Loading…"
680	        } else if !self.query.trim().is_empty() {
681	            "No matches"
682	        } else {
683	            match self.tab {
684	                PaletteTab::Files => "No files",
685	                PaletteTab::Commands => "No commands",
686	                PaletteTab::Skills => "No skills",
687	                PaletteTab::Agents => "No agents",
688	                PaletteTab::System => "",
689	            }
690	        }
691	    }
692	}
693	
694	/// A result's row: its icon, its text with the matched characters
695	/// highlighted, and a description or shortcut when it has one.
696	fn item(shown: &Shown, icon: IconName, cx: &App) -> CommandItem {
697	    let theme = cx.theme();
698	    let muted = theme.muted_foreground;
699	    let highlight = HighlightStyle {
700	        color: Some(theme.primary),
701	        font_weight: Some(FontWeight::BOLD),
702	        ..HighlightStyle::default()
703	    };
704	    let text: SharedString = shown.candidate.text().to_string().into();
705	    let highlights: Vec<(Range<usize>, HighlightStyle)> = shown
706	        .positions
707	        .iter()
708	        .map(|&start| {
709	            let len = text[start..].chars().next().map_or(1, char::len_utf8);
710	            (start..start + len, highlight)
711	        })
712	        .collect();
713	    let description = match &shown.candidate {
714	        Candidate::Mention(invocable) => invocable.description.clone(),
715	        _ => None,
716	    };
717	    let enabled = !matches!(shown.candidate, Candidate::System { enabled: false, .. });
718	    let quit = matches!(
719	        shown.candidate,
720	        Candidate::System {
721	            command: SystemCommand::Quit,
722	            ..
723	        }
724	    );
725	
726	    CommandItem::new()
727	        .label(text.clone())
728	        .disabled(!enabled)
729	        .child(move |window, _| {
730	            h_flex()
731	                .flex_1()
732	                .min_w_0()
733	                .gap_2()
734	                .items_center()
735	                .child(
736	                    Icon::new(icon.clone())
737	                        .small()
738	                        .flex_none()
739	                        .text_color(muted),
740	                )
741	                .child(
742	                    div()
743	                        .flex_none()
744	                        .max_w(relative(0.6))
745	                        .truncate()
746	                        .child(StyledText::new(text.clone()).with_highlights(highlights.clone())),
747	                )
748	                .when_some(description.clone(), |row, description| {
749	                    row.child(
750	                        div()
751	                            .flex_1()
752	                            .min_w_0()
753	                            .truncate()
754	                            .text_color(muted)
755	                            .child(description),
756	                    )
757	                })
758	                .when(quit, |row| {
759	                    row.children(
760	                        Kbd::binding_for_action(&Quit, None, window).map(|kbd| kbd.ml_auto()),
761	                    )
762	                })
763	        })
764	}
765	
766	impl Render for Palette {
767	    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
768	        let this = cx.entity().downgrade();
769	        let icon = self.tab.icon();
770	        let searching = self.search.is_some();
771	        // The harness's search takes the results' place.
772	        let items: Vec<CommandItem> = if searching {
773	            Vec::new()
774	        } else {
775	            self.shown
776	                .iter()
777	                .map(|shown| item(shown, icon.clone(), cx))
778	                .collect()
779	        };
780	        let empty: SharedString = self.empty_text().into();
781	        let selected_tab = PaletteTab::ALL
782	            .iter()
783	            .position(|tab| *tab == self.tab)
784	            .unwrap_or(0);
785	
786	        let command = Command::new(&self.command)
787	            .bordered(false)
788	            // Results are fuzzy matched and ranked here instead.
789	            .filterable(false)
790	            .max_h(MAX_LIST_HEIGHT)
791	            .placeholder(self.tab.placeholder())
792	            .header({
793	                let this = this.clone();
794	                move |_, _, _| {
795	                    let this = this.clone();
796	                    TabBar::new("palette-tabs")
797	                        .selected_index(selected_tab)
798	                        .on_click(move |ix, window, cx| {
799	                            this.update(cx, |this, cx| {
800	                                this.set_tab(PaletteTab::ALL[*ix], window, cx)
801	                            })
802	                            .ok();
803	                        })
804	                        .children(PaletteTab::ALL.map(|tab| Tab::new().label(tab.label())))
805	                }
806	            })
807	            .items(items)
808	            .empty({
809	                let this = this.clone();
810	                move |_, _, cx| {
811	                    let palette = this.upgrade();
812	                    let search = palette
813	                        .as_ref()
814	                        .and_then(|palette| palette.read(cx).search.as_ref());
815	                    match search {
816	                        Some(search) => {
817	                            let table = div()
818	                                .id("palette-search")
819	                                .w_full()
820	                                // Inside the list's padding.
821	                                .max_h(MAX_LIST_HEIGHT - px(8.))
822	                                .overflow_y_scroll()
823	                                .child(output_table(0, &search.reply, None, cx));
824	                            // Lets UI tests find the search; inert in normal builds.
825	                            gpui_kit::TestSupportExt::test_support(table).into_any_element()
826	                        }
827	                        None => div()
828	                            .py_6()
829	                            .w_full()
830	                            .text_center()
831	                            .text_sm()
832	                            .text_color(cx.theme().muted_foreground)
833	                            .child(empty.clone())
834	                            .into_any_element(),
835	                    }
836	                }
837	            })
838	            .on_query({
839	                let this = this.clone();
840	                move |query, _, cx| {
841	                    this.update(cx, |this, cx| this.set_query(query, cx)).ok();
842	                }
843	            })
844	            .on_confirm(move |ix, window, cx| {
845	                this.update(cx, |this, cx| this.pick(ix.row, window, cx))
846	                    .ok();
847	            });
848	
849	        let palette = v_flex()
850	            .id("palette")
851	            .key_context(CONTEXT)
852	            .track_focus(&self.focus_handle)
853	            .w_full()
854	            .overflow_hidden()
855	            // Enter with nothing matched hands the search to the harness.
856	            .capture_action(cx.listener(|this, action: &Confirm, window, cx| {
857	                let nothing_found = this.files.is_some() && this.shown.is_empty();
858	                if !action.secondary && nothing_found && this.can_search_files() {
859	                    cx.stop_propagation();
860	                    this.search_files(window, cx);
861	                }
862	            }))
863	            // Ctrl/Cmd+Enter, as the search field reads it.
864	            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
865	                if action.secondary && this.tab == PaletteTab::Files {
866	                    cx.stop_propagation();
867	                    this.search_files(window, cx);
868	                }
869	            }))
870	            .on_action(
871	                cx.listener(|this, _: &SearchFiles, window, cx| this.search_files(window, cx)),
872	            )
873	            // Tab and Shift+Tab switch tabs rather than reaching the search
874	            // field, which keeps focus.
875	            .capture_action(cx.listener(|this, _: &IndentInline, window, cx| {
876	                cx.stop_propagation();
877	                this.cycle(1, window, cx);
878	            }))
879	            .capture_action(cx.listener(|this, _: &OutdentInline, window, cx| {
880	                cx.stop_propagation();
881	                this.cycle(-1, window, cx);
882	            }))
883	            .child(command);
884	        // Lets UI tests find the palette; inert in normal builds.
885	        gpui_kit::TestSupportExt::test_support(palette)
886	    }
887	}
888	
889	#[cfg(test)]
890	mod tests {
891	    use std::fs;
892	    use std::path::{Path, PathBuf};
893	
894	    use super::{Candidate, MAX_RESULTS, found_files, list_files, rank, search_system_prompt};
895	
896	    /// The search looks through this repository's spec and code, from its
897	    /// `piton.config.pi`, then the application's and the harness's directories.
898	    #[test]
899	    fn search_prompt_orders_configured_locations() {
900	        let prompt = search_system_prompt(Path::new(env!("CARGO_MANIFEST_DIR")));
901	        assert!(prompt.contains(
902	            "\n1. the spec, in ./spec\n2. the code, in ./src\n3. .suspense\n4. .claude\n"
903	        ));
904	    }
905	
906	    /// The harness's answer names files that exist, relative to the project,
907	    /// whether or not it strayed from JSON alone.
908	    #[test]
909	    fn reads_the_files_the_harness_found() {
910	        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/palette-found-test");
911	        fs::remove_dir_all(&root).ok();
912	        fs::create_dir_all(root.join("src")).unwrap();
913	        fs::write(root.join("src/a.rs"), "").unwrap();
914	        fs::write(root.join("b.md"), "").unwrap();
915	
916	        assert_eq!(
917	            found_files(r#"{"files": ["src/a.rs"]}"#, &root),
918	            [root.join("src/a.rs")]
919	        );
920	        assert_eq!(
921	            found_files(
922	                "Found them:\n```json\n{\"files\": [\"./b.md\", \"gone.rs\", \"src/a.rs\", \"b.md\"]}\n```",
923	                &root
924	            ),
925	            [root.join("b.md"), root.join("src/a.rs")]
926	        );
927	        assert!(found_files(r#"{"files": []}"#, &root).is_empty());
928	        assert!(found_files("I could not find it.", &root).is_empty());
929	        fs::remove_dir_all(&root).ok();
930	    }
931	
932	    fn file(label: &str) -> Candidate {
933	        Candidate::File {
934	            path: PathBuf::from(label),
935	            label: label.to_string().into(),
936	            name_start: label.rfind('/').map_or(0, |ix| ix + 1),
937	        }
938	    }
939	
940	    fn texts(query: &str, candidates: &[Candidate]) -> Vec<String> {
941	        rank(query, candidates)
942	            .into_iter()
943	            .map(|shown| shown.candidate.text().to_string())
944	            .collect()
945	    }
946	
947	    #[test]
948	    fn ranks_the_best_matches_first() {
949	        let files = [
950	            file("spec/scope/application/MainWindow.pi"),
951	            file("src/main_window.rs"),
952	            file("src/main.rs"),
953	            file("src/toolbar.rs"),
954	        ];
955	        assert_eq!(
956	            texts("main", &files)[..2],
957	            ["src/main.rs", "src/main_window.rs"]
958	        );
959	        assert_eq!(
960	            texts("mwin", &files),
961	            ["src/main_window.rs", "spec/scope/application/MainWindow.pi"]
962	        );
963	        assert_eq!(texts("zzz", &files), Vec::<String>::new());
964	        // An empty search keeps the order.
965	        assert_eq!(texts("", &files)[0], "spec/scope/application/MainWindow.pi");
966	
967	        let many: Vec<Candidate> = (0..MAX_RESULTS * 2)
968	            .map(|ix| file(&format!("f{ix}.rs")))
969	            .collect();
970	        assert_eq!(rank("", &many).len(), MAX_RESULTS);
971	        assert_eq!(rank("f", &many).len(), MAX_RESULTS);
972	    }
973	
974	    #[test]
975	    fn lists_files_by_path_leaving_out_ignored_ones() {
976	        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/palette-files-test");
977	        fs::remove_dir_all(&root).ok();
978	        for path in [
979	            "src/b.rs",
980	            "src/A.rs",
981	            ".claude/skills/x/SKILL.md",
982	            "build/out.txt",
983	            ".git/HEAD",
984	            "README.md",
985	        ] {
986	            let path = root.join(path);
987	            fs::create_dir_all(path.parent().unwrap()).unwrap();
988	            fs::write(path, "").unwrap();
989	        }
990	        fs::write(root.join(".gitignore"), "/build\n").unwrap();
991	
992	        let labels: Vec<String> = list_files(&root)
993	            .iter()
994	            .map(|file| file.text().to_string())
995	            .collect();
996	        assert_eq!(
997	            labels,
998	            [
999	                ".claude/skills/x/SKILL.md",
1000	                ".gitignore",
1001	                "README.md",
1002	                "src/A.rs",
1003	                "src/b.rs"
1004	            ]
