4	use gpui_kit::*;
5	
6	/// The raw output of one harness run, one line per event, as it arrives.
7	pub struct HarnessRun {
8	    lines: Vec<String>,
9	    done: bool,
10	}
11	
12	impl HarnessRun {
13	    pub fn lines(&self) -> &[String] {
14	        &self.lines
15	    }
16	
17	    pub fn is_done(&self) -> bool {
18	        self.done
19	    }
20	
21	    pub fn push_line(&mut self, line: String, cx: &mut Context<Self>) {
22	        self.lines.push(line);
23	        cx.notify();
24	    }
25	
26	    pub fn finish(&mut self, cx: &mut Context<Self>) {
27	        self.done = true;
28	        cx.notify();
29	    }
30	}
31	
32	/// The session's harness runs; observers hear when a new run starts.
33	#[derive(Default)]
34	pub struct HarnessRuns {
35	    latest: Option<Entity<HarnessRun>>,
36	}
37	
38	impl Global for HarnessRuns {}
39	
40	impl HarnessRuns {
41	    pub fn init(cx: &mut App) {
42	        cx.set_global(Self::default());
43	    }
44	
45	    /// Starts a new run and makes it the latest.
46	    pub fn start(cx: &mut App) -> Entity<HarnessRun> {
47	        let run = cx.new(|_| HarnessRun {
48	            lines: Vec::new(),
49	            done: false,
50	        });
51	        cx.update_global::<Self, _>(|runs, _| runs.latest = Some(run.clone()));
52	        run
53	    }
54	
55	    /// The run still streaming, if any.
56	    pub fn in_progress(cx: &App) -> Option<Entity<HarnessRun>> {
57	        cx.global::<Self>()
58	            .latest
59	            .clone()
60	            .filter(|run| !run.read(cx).is_done())
61	    }
62	}
