//! Harness stream: a realtime view of one harness run's raw output, pretty
//! formatted and monospace with JSON highlighting, just the text with no border
//! or decoration. It follows the newest line while scrolled to the bottom, and
//! leaves the view alone while scrolled up. A stream follows the run in
//! progress when it opens, and each run that starts after it, one after the
//! other.

use gpui_kit::component::input::{Editor, EditorState};
use gpui_kit::*;

use crate::harness_run::{HarnessRun, HarnessRuns};

pub struct HarnessStream {
    editor: Entity<EditorState>,
    run: Option<Entity<HarnessRun>>,
    /// How many of the run's lines the editor already shows.
    shown: usize,
    /// How many rows the editor's text spans.
    rows: usize,
    /// New lines arrived that the view has not scrolled to yet.
    follow_pending: bool,
    _runs: Subscription,
    _run: Option<Subscription>,
}

impl HarnessStream {
    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
        let editor = cx.new(|cx| {
            EditorState::new(window, cx)
                .language("json")
                .line_number(false)
                .folding(false)
                // One row per output line, so the newest line's position is
                // known without the editor's private wrap layout.
                .soft_wrap(false)
                .placeholder("Waiting for the next run…")
        });

        // Each run that starts is followed in turn, its output after the last's.
        let runs = cx.observe_global_in::<HarnessRuns>(window, |this, window, cx| {
            if let Some(run) = HarnessRuns::in_progress(cx)
                && this.run.as_ref() != Some(&run)
            {
                this.attach(run, window, cx);
            }
        });
        let mut this = Self {
            editor,
            run: None,
            shown: 0,
            rows: 0,
            follow_pending: false,
            _runs: runs,
            _run: None,
        };
        if let Some(run) = HarnessRuns::in_progress(cx) {
            this.attach(run, window, cx);
        }
        this
    }

    fn attach(&mut self, run: Entity<HarnessRun>, window: &mut Window, cx: &mut Context<Self>) {
        // Anything the previous run still had is shown before moving on.
        self.show_new_lines(window, cx);
        self._run = Some(cx.observe_in(&run, window, |this, _, window, cx| {
            this.show_new_lines(window, cx)
        }));
        self.run = Some(run);
        self.shown = 0;
        self.show_new_lines(window, cx);
    }

    /// Appends the run's lines the editor does not show yet. If the view was
    /// at the bottom, it scrolls to them once the editor has laid them out;
    /// otherwise auto scroll waits until the user scrolls back down.
    fn show_new_lines(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(run) = &self.run else {
            return;
        };
        let lines = run.read(cx).lines();
        let mut text = String::new();
        for line in lines.iter().skip(self.shown) {
            // A blank line between events, whichever run they came from.
            if self.rows > 0 || !text.is_empty() {
                text.push_str("\n\n");
            }
            text.push_str(&pretty(line));
        }
        self.shown = lines.len();

        if !text.is_empty() {
            // Measured before the new rows count, against the text on screen.
            // A scroll still pending keeps following.
            self.follow_pending = self.follow_pending || self.is_at_bottom(cx);
            // Soft wrap is off, so each line of text is one row; only the
            // first text appended opens a row without a line break.
            self.rows = self.rows.max(1) + text.matches('\n').count();
            let follow = self.follow_pending;
            self.editor.update(cx, |editor, cx| {
                // Moving the cursor to the end scrolls to it: keep the view
                // where the user left it unless following.
                let offset = editor.scroll_offset();
                let end = editor.value().len();
                editor.set_selected_range(end..end, cx);
                editor.insert(text, window, cx);
                if !follow {
                    editor.set_scroll_offset(offset, cx);
                }
            });
        }
        cx.notify();
    }

    /// Whether the view shows the last line of the text it holds. Before the
    /// editor is laid out there is nothing to scroll away from, so it is.
    fn is_at_bottom(&self, cx: &App) -> bool {
        let editor = self.editor.read(cx);
        let (Some(line_height), Some(bounds)) = (editor.line_height(), editor.text_bounds()) else {
            return true;
        };
        let bottom = (bounds.size.height - line_height * self.rows as f32).min(px(0.));
        editor.scroll_offset().y <= bottom + px(1.)
    }

    /// Scrolls so the last line sits at the bottom of the view, returning
    /// whether the editor had been laid out to do so. The editor only scrolls
    /// to its cursor while focused, and a stream never is.
    fn scroll_to_newest(&mut self, cx: &mut Context<Self>) -> bool {
        let rows = self.rows;
        self.editor.update(cx, |editor, cx| {
            let (Some(line_height), Some(bounds)) = (editor.line_height(), editor.text_bounds())
            else {
                return false;
            };
            let bottom = (bounds.size.height - line_height * rows as f32).min(px(0.));
            let x = editor.scroll_offset().x;
            editor.set_scroll_offset(point(x, bottom), cx);
            true
        })
    }
}

/// One line of output, indented across lines if it is JSON, else as it is.
fn pretty(line: &str) -> String {
    serde_json::from_str::<serde_json::Value>(line)
        .ok()
        .and_then(|value| serde_json::to_string_pretty(&value).ok())
        .unwrap_or_else(|| line.to_string())
}

impl Render for HarnessStream {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        // Painted after the editor, so its layout of any new lines is known:
        // scroll to them then. Only new output scrolls, so the stream can
        // always be scrolled by hand.
        let this = cx.entity().downgrade();
        let follow_newest = canvas(
            |_, _, _| {},
            move |_, _, _, cx| {
                this.update(cx, |this, cx| {
                    if this.follow_pending && this.scroll_to_newest(cx) {
                        this.follow_pending = false;
                    }
                })
                .ok();
            },
        )
        .absolute()
        .size_full();

        div()
            .relative()
            .size_full()
            .child(
                Editor::new(&self.editor)
                    .readonly(true)
                    // Just the text: no border or background.
                    .appearance(false)
                    .h(relative(1.)),
            )
            .child(follow_newest)
    }
}

#[cfg(test)]
mod tests {
    // Explicit imports: globbing `gpui_kit::*` would bring in GPUI's `test`
    // macro and shadow Rust's `#[test]`.
    use std::time::Duration;

    use gpui_kit::component::Root;
    use gpui_kit::test::{TestAppContextExt as _, TestWindowExt as _};
    use gpui_kit::{AppContext as _, TestAppContext};

    use super::{HarnessStream, pretty};
    use crate::harness_run::HarnessRuns;

    /// JSON is indented across lines; anything else is left as it arrived.
    #[test]
    fn pretty_formats_json_lines() {
        assert_eq!(
            pretty(r#"{"type":"result","ok":true}"#),
            "{\n  \"type\": \"result\",\n  \"ok\": true\n}"
        );
        assert_eq!(pretty("not json {"), "not json {");
    }

    /// A stream left open follows each run that starts, after the last one's
    /// output.
    #[gpui_kit::test]
    async fn follows_every_run_that_starts(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            HarnessRuns::init(cx);
        });
        let mut stream = None;
        cx.add_window(|window, cx| {
            let view = cx.new(|cx| HarnessStream::new(window, cx));
            stream = Some(view.clone());
            Root::new(view, window, cx)
        });
        let stream = stream.unwrap();
        let editor = stream.read_with(cx, |stream, _| stream.editor.clone());

        for line in ["first", "second"] {
            let run = cx.update(HarnessRuns::start);
            cx.update(|cx| {
                run.update(cx, |run, cx| {
                    run.push_line(line.to_string(), cx);
                    run.finish(cx);
                })
            });
            cx.run_until_parked();
        }

        let text = editor.read_with(cx, |editor, _| editor.value().to_string());
        assert_eq!(text, "first\n\nsecond");
    }

    /// A stream opened between runs follows the next run, shows each line
    /// pretty formatted as it arrives, and keeps the newest line in view.
    #[gpui_kit::test]
    async fn follows_the_next_run_to_its_newest_line(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            HarnessRuns::init(cx);
        });
        let mut stream = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| HarnessStream::new(window, cx));
            stream = Some(view.clone());
            Root::new(view, window, cx)
        });
        let stream = stream.unwrap();
        let handle = window.into();

        let run = cx.update(HarnessRuns::start);
        let lines: Vec<String> = (0..80)
            .map(|ix| format!("{{\"type\":\"stream_event\",\"index\":{ix}}}"))
            .collect();
        cx.update(|cx| {
            run.update(cx, |run, cx| {
                for line in &lines {
                    run.push_line(line.clone(), cx);
                }
            })
        });

        let editor = stream.read_with(cx, |stream, _| stream.editor.clone());
        let attached = stream.read_with(cx, |stream, _| stream.run.is_some());
        assert!(attached, "the stream did not follow the run that started");

        let expected = lines
            .iter()
            .map(|line| pretty(line))
            .collect::<Vec<_>>()
            .join("\n\n");
        cx.wait_for(handle, Duration::from_secs(2), |_, cx| {
            editor.read(cx).value().len() == expected.len()
        })
        .await;
        let text = editor.read_with(cx, |editor, _| editor.value().to_string());
        assert_eq!(text, expected);
        let rows = expected.lines().count();
        assert_eq!(stream.read_with(cx, |stream, _| stream.rows), rows);

        // Let the editor lay out the new text, then the stream scroll to it.
        for _ in 0..3 {
            cx.run_until_parked();
            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
                .unwrap();
        }
        let (offset, bounds, line_height) = editor.read_with(cx, |editor, _| {
            (
                editor.scroll_offset(),
                editor.text_bounds(),
                editor.line_height(),
            )
        });
        let (bounds, line_height) = (bounds.unwrap(), line_height.unwrap());
        let content = line_height * rows as f32;
        assert!(
            offset.y < gpui_kit::px(0.),
            "the stream is not scrolled: offset {offset:?}, text bounds {bounds:?}"
        );
        assert!(
            content + offset.y <= bounds.size.height + line_height,
            "the newest line is below the view: offset {offset:?}, {content:?} of content \
             in {bounds:?}"
        );

        let push = |from: usize, cx: &mut TestAppContext| {
            cx.update(|cx| {
                run.update(cx, |run, cx| {
                    for ix in from..from + 20 {
                        run.push_line(format!("{{\"index\":{ix}}}"), cx);
                    }
                })
            });
            for _ in 0..3 {
                cx.run_until_parked();
                cx.update_window(handle, |_, window, cx| window.render_frame(cx))
                    .unwrap();
            }
        };

        // Scrolled up, new output leaves the view where it is.
        cx.update(|cx| {
            editor.update(cx, |editor, cx| {
                editor.set_scroll_offset(gpui_kit::point(gpui_kit::px(0.), gpui_kit::px(0.)), cx)
            })
        });
        push(80, cx);
        let offset = editor.read_with(cx, |editor, _| editor.scroll_offset());
        assert_eq!(offset.y, gpui_kit::px(0.), "auto scroll was not suspended");

        // Back at the bottom, it follows new output again.
        stream.update(cx, |stream, cx| {
            stream.scroll_to_newest(cx);
        });
        push(100, cx);
        let (offset, rows) = stream.read_with(cx, |stream, cx| {
            (editor.read(cx).scroll_offset(), stream.rows)
        });
        let content = line_height * rows as f32;
        assert!(
            content + offset.y <= bounds.size.height + line_height,
            "auto scroll did not resume at the bottom: offset {offset:?}, {content:?} of \
             content in {bounds:?}"
        );
    }
}

