            .as_ref()
            .map(|dir| dir.display().to_string().into())
            .unwrap_or_else(|| "Select a piton.config.pi file".into());

        let side = || {
            div()
                .flex_1()
                .min_w_0()
                .flex()
                .flex_row()
                .items_center()
                .gap_2()
        };

        div()
            .flex()
            .flex_row()
            .items_center()
            .gap_2()
            .px_3()
            .py_2()
            .border_b_1()
            .border_color(cx.theme().border)
            .child(
