    // its container.
    for _ in 0..3 {
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| window.render_frame(cx))
            .unwrap();
    }

    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        let viewport = window.viewport_size();
        let send = window.find("send").bounds();
        let stream = window.find("stream").bounds();
        assert!(
            stream.left() >= send.right() && stream.size.width > gpui_kit::px(0.),
            "stream is not beside prompt mode (Send at {send:?}): {stream:?} in {viewport:?}"
        );
        assert!(
            stream.right() <= viewport.width + gpui_kit::px(1.),
            "stream runs past the window: {stream:?} in {viewport:?}"
        );
    })
    .unwrap();

    cx.update_window(handle, |_, window, cx| window.click("raw-output", cx))
        .unwrap();
    cx.wait_for(handle, TIMEOUT, |window, _| {
        window.try_find("stream").is_none()
    })
    .await;
}

